const staticData = $getWorkflowStaticData('global');
const lastPollTime = staticData.lastPollTime || (Date.now() - 60 * 60 * 1000);

return [{ json: { lastPollTime } }];

const item = $input.first().json;
const props = item.properties || {};

const contact = {
  email: props.email || '',
  firstname: props.firstname || '',
  lastname: props.lastname || '',
  hubspotContactId: item.id || null,
  createdAt: props.createdate || null,
  company: props.company || '',
  proses: props.proses_yang_ingin_diotomatisasi || '',
  tools: props.tools_digunakan || '',
  ukuranTim: props.ukuran_tim || '',
  urgensi: props.urgensi || ''
};

if (!contact.email) {
  throw new Error('ExtractContactData: field email tidak ditemukan pada contact ' + contact.hubspotContactId);
}

return [{ json: contact }];

const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content || '';

const qualMatch = content.match(/KUALIFIKASI:\s*([\s\S]*?)(?:\n\s*DRAFT EMAIL:|DRAFT EMAIL:)/i);
const emailMatch = content.match(/DRAFT EMAIL:\s*([\s\S]*)/i);

const qualification = qualMatch ? qualMatch[1].trim() : content.trim();
const draftEmail = emailMatch ? emailMatch[1].trim() : '';

const contact = $('ExtractContactData').item.json;

return [{
  json: {
    hubspotContactId: contact.hubspotContactId,
    firstname: contact.firstname,
    lastname: contact.lastname,
    email: contact.email,
    qualification,
    draftEmail
  }
}];
